private static void littleEndianPutInt(OutputStream out, int value) throws IOException {
    out.write((value) & 0xFF);
    out.write((value >> 8) & 0xFF);
    out.write((value >> 16) & 0xFF);
    out.write((value >> 24) & 0xFF);
}

public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    try {
        byte[] data = schema.toByteArray(message);
        int size = data.length;
        if (size > Integer.MAX_VALUE - 5) {
            throw new IOException("Message is too large to write");
        }
        out.writeCodedLong(size);
        out.write(data, 0, size);
        return size;
    } catch (IOException e) {
        throw e;
    } catch (Exception e) {
        throw new IOException("Error serializing message", e);
    }
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toBytes(message);
    int size = data.length;
    buffer = ensureCapacity(buffer, size + CodedOutputStream.computeRawVarint32Size(size));
    CodedOutputStream codedOut = CodedOutputStream.newInstance(buffer);
    codedOut.writeRawVarint32(size);
    codedOut.writeRawBytes(data);
    codedOut.flush();
    return size;
}

