static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long day = timeBucket % 100;

    if (dayStep == 1) {
        return timeBucket;
    } else if (dayStep == 7) {
        long adjustedDay = day - (day % 7);
        if (adjustedDay == 0) {
            adjustedDay = 7;
        }
        return year * 10000 + month * 100 + adjustedDay;
    } else if (dayStep >= 8 && dayStep <= 31) {
        long adjustedDay = day - (day % dayStep);
        if (adjustedDay == 0) {
            adjustedDay = dayStep;
        }
        return year * 10000 + month * 100 + adjustedDay;
    } else {
        throw new IllegalArgumentException("Unsupported dayStep: " + dayStep);
    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long day = timeBucket % 100;

    if (day <= dayStep) {
        day = 1;
    } else {
        day = 1 + ((day - 1) / dayStep) * dayStep;
    }

    return year * 10000 + month * 100 + day;
}

