    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);
    int remainder = day % dayStep;
    day = remainder == 0 ? day - dayStep + 1 : day - remainder + 1;
    return year * 10000 + month * 100 + day;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract year, month, and day from the time bucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Adjust the day based on the dayStep
    int adjustedDay = day - (day - 1) % dayStep;

    // Handle the edge case where the adjusted day is less than the original day
    if (adjustedDay < day) {
        month = month - 1; // Move to the previous month
        if (month == 0) {
            year = year - 1; // Move to the previous year
            month = 12;
        }
        int daysInPreviousMonth = (month == 12) ? 31 : 30; // February is not considered for simplicity
        if (day == 29 && month == 2) {
            day = 28; // Adjust for leap year
        } else {
            day = daysInPreviousMonth; // Adjust for the last day of the previous month
        }
    }

    // Adjust the month and year if necessary
    if (month == 0) {
        year = year - 1; // Move to the previous year
        month = 12;
    }

    // Reconstruct the time bucket with the adjusted day
    long compressedTimeBucket = (year * 10000) + (month * 100) + adjustedDay;

    return compressedTimeBucket;
}

