    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    int dayPart = (int) (timeBucket % 100);
    if (dayPart % dayStep == 0) {
        return timeBucket;
    } else {
        int newDayPart = dayPart + (dayStep - (dayPart % dayStep));
        return timeBucket - dayPart + newDayPart;
    }
