    int len = str.length();
    if (len == 0) {
        return lb;
    }

    byte[] buffer = lb.buffer();
    int pos = lb.position();
    if (pos + len > buffer.length) {
        buffer = lb.allocate(len + pos);
        pos = 0;
        lb.position(0);
    }

    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c <= 0x007F) {
            buffer[pos++] = (byte) c;
        } else if (c <= 0x07FF) {
            buffer[pos++] = (byte) (0xC0 | (c >> 6));
            buffer[pos++] = (byte) (0x80 | (c & 0x3F));
        } else {
            buffer[pos++] = (byte) (0xE0 | (c >> 12));
            buffer[pos++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            buffer[pos++] = (byte) (0x80 | (c & 0x3F));
        }
    }

    lb.position(pos);
    return lb;
}

