private void putAbstractType(final AbstractType type) {
    switch (type.getKind()) {
        case REFERENCE:
            stackMapTableEntries.add(new ReferenceTypeInfo());
            break;
        case NULL:
            stackMapTableEntries.add(new NullTypeInfo());
            break;
        case UNINITIALIZED_THIS:
            stackMapTableEntries.add(new UninitializedThisTypeInfo());
            break;
        case UNINITIALIZED:
            stackMapTableEntries.add(new UninitializedTypeInfo());
            break;
        case ITEM_TOP:
            stackMapTableEntries.add(new TopTypeInfo());
            break;
        case ITEM_INTEGER:
            stackMapTableEntries.add(new IntegerTypeInfo());
            break;
        case ITEM_FLOAT:
            stackMapTableEntries.add(new FloatTypeInfo());
            break;
        case ITEM_LONG:
            stackMapTableEntries.add(new LongTypeInfo());
            break;
        case ITEM_DOUBLE:
            stackMapTableEntries.add(new DoubleTypeInfo());
            break;
        case ITEM_CLASS:
            stackMapTableEntries.add(new ClassTypeInfo(((ClassType) type).getInternalName()));
            break;
        case ITEM_OBJECT:
            stackMapTableEntries.add(new ObjectTypeInfo(((ObjectType) type).getInternalName()));
            break;
        case ITEM_UNINITIALIZED_VARIABLE:
            stackMapTableEntries.add(new UninitializedVariableTypeInfo(((UninitializedVariableType) type).getOffset()));
            break;
        default:
            throw new IllegalArgumentException("Invalid type kind");
    }
}

