/**
 * Either finds and returns a circulator to the node on the boundary of the component, which satisfies the  {@code predicate} or returns a circulator to the {@code stop} node.
 * @param predicate the condition the desired node should satisfy
 * @param start the node to start the search from
 * @param stop the node to end the search with
 * @param dir the direction to start the traversal in
 * @return a circulator to the node satisfying the {@code predicate} or to the {@code stop} node
 */
private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (circulator.hasNext()) {
        Node node = circulator.current();
        if (predicate.test(node) || node == stop) {
            return circulator;
        }
        circulator.next();
    }
    return new OuterFaceCirculator(stop, dir);
}

OuterFaceCirculator function(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Initialize the circulator with the start node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    // Traverse the mesh in the specified direction
    while (circulator.hasNext()) {
        Node currentNode = circulator.current();
        if (predicate.test(currentNode)) {
            return circulator; // Found a node satisfying the predicate
        }
        if (currentNode.equals(stop)) {
            return circulator; // Reached the stop node
        }
        circulator.next();
    }

    return circulator; // Return the current circulator if no node was found
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (!circulator.isDone()) {
        if (predicate.test(circulator.currentNode())) {
            return circulator;
        }
        if (circulator.currentNode() == stop) {
            return circulator;
        }
        circulator.advance();
    }
    return circulator; // Returns the stop node if no matching node is found
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("Predicate, start, and stop nodes cannot be null");
    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    while (circulator.current() != stop) {
        if (predicate.test(circulator.current())) {
            return circulator;
        }
        circulator = circulator.successor();
    }

    return circulator;
}

