protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        throw new IllegalArgumentException("Tour Set cannot be null or empty");
    }
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    Iterator<E> iterator = tour.iterator();
    E firstEdge = iterator.next();
    V source = graph.getEdgeSource(firstEdge);
    V target = graph.getEdgeTarget(firstEdge);
    DefaultGraphPath<V,E> path = new DefaultGraphPath<>(source, firstEdge, target);

    while (iterator.hasNext()) {
        E edge = iterator.next();
        if (!graph.containsEdge(source, edge)) {
            throw new IllegalArgumentException("Edge " + edge + " does not match the source node " + source);
        }
        source = target;
        target = graph.getEdgeTarget(edge);
        path = path.andThen(edge, target);
    }

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour.isEmpty()){
        return null;
    }
    GraphPath<V,E> path = new WalkBasedPath<V,E>(graph);
    Iterator<E> iter = tour.iterator();
    E firstEdge = iter.next();
    V startVertex = graph.getEdgeSource(firstEdge);
    V endVertex = graph.getEdgeTarget(firstEdge);
    path.addNode(startVertex);
    while (iter.hasNext()){
        E edge = iter.next();
        if (graph.getEdgeSource(edge).equals(endVertex)){
            path.addEdge(edge);
        } else {
            path.addEdge(edge);
            path.addNode(graph.getEdgeTarget(edge));
        }
        endVertex = graph.getEdgeTarget(edge);
    }
    path.addNode(endVertex);
    return path;
}

