    Iterator<E> iterator = tour.iterator();
    E firstEdge = iterator.next();
    V startVertex = graph.getEdgeSource(firstEdge);
    V endVertex = graph.getEdgeTarget(firstEdge);

    List<E> path = new ArrayList<>();
    path.add(firstEdge);

    while (iterator.hasNext()) {
        E edge = iterator.next();
        V nextVertex = graph.getEdgeSource(edge);
        if (nextVertex.equals(endVertex)) {
            break;
        }
        if (path.contains(edge) || !graph.containsEdge(startVertex, nextVertex)) {
            throw new IllegalArgumentException("Invalid tour set");
        }
        path.add(edge);
        startVertex = endVertex;
        endVertex = nextVertex;
    }

    GraphPath<V,E> graphPath = new WalkGraphPath<>(graph, startVertex, path);
    return graphPath;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input tour and graph cannot be null");
    }

    List<E> edges = new ArrayList<>(tour);
    if (edges.isEmpty()) {
        return graph.createPath();
    }

    V currentVertex = edges.get(0).getEndpoint(graph.getEdgeSource(edges.get(0)));
    List<V> pathVertices = new ArrayList<>();
    pathVertices.add(currentVertex);

    for (E edge : edges) {
        V nextVertex = edge.getOppositeVertex(graph, currentVertex);
        if (pathVertices.contains(nextVertex)) {
            currentVertex = nextVertex;
            break;
        } else {
            pathVertices.add(nextVertex);
            currentVertex = nextVertex;
        }
    }

    return graph.createPath(pathVertices);
}

