private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }

    List<Integer> suffixSumList = new ArrayList<>();
    long totalSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        if (i == bounds.size() - 1) {
            suffixSumList.add(bounds.get(i));
        } else {
            int previousSum = suffixSumList.get(suffixSumList.size() - 1);
            suffixSumList.add(bounds.get(i) + previousSum);
        }
        totalSum += bounds.get(i);
    }

    Collections.reverse(suffixSumList);

    return new Pair<>(suffixSumList, totalSum);
