    try {
        if (row >= 0 && row < table.getRowCount()) {
            table.setRowSelectionInterval(row, row);
            Rectangle visibleRect = table.getCellRect(row, 0, true);
            if (visibleRect != null) {
                pane.getViewport().scrollRectToVisible(visibleRect);
            }
        }
    } catch (ArrayIndexOutOfBoundsException e) {
        // Handle invalid row index
        System.err.println("Invalid row index: " + row);
    } catch (NullPointerException e) {
        // Handle null table or pane
        System.err.println("Null table or pane provided");
    }
