public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table.getRowCount() <= row || row < 0) {
        throw new IllegalArgumentException("Invalid row index: " + row);
    }

    table.setRowSelectionInterval(row, row);
    int rowHeight = table.getRowHeight();
    int rowPosition = table.getCellRect(row, 0, true).y;
    int visibleRowCount = pane.getViewport().getHeight() / rowHeight;

    if (rowPosition < pane.getVerticalScrollBar().getValue()) {
        pane.getVerticalScrollBar().setValue(rowPosition);
    } else if (rowPosition + rowHeight > pane.getVerticalScrollBar().getValue() + pane.getViewport().getHeight()) {
        pane.getVerticalScrollBar().setValue(rowPosition - (visibleRowCount * rowHeight) / 2);
    }

    SwingUtilities.invokeLater(() -> {
        table.scrollRectToVisible(table.getCellRect(row, 0, true));
        table.repaint();
    });
}

