private void ensureCapacity(int additionalCapacity) {
    if (this.data.remaining() < additionalCapacity) {
        int newSize = Math.max(this.data.capacity() * 2, this.data.capacity() + additionalCapacity);
        ByteBuffer newData = ByteBuffer.allocate(newSize);
        this.data.flip();
        newData.put(this.data);
        this.data = newData;
    }
}

