public void abbreviate(final int nameStart, final StringBuffer buf) {
    long pos = nameStart;
    long max = buf.length();
    long len = max - pos;

    if (len <= 3) {
        buf.append('.');
        return;
    }

    if ((len == 4) && (max >= 4)) {
        buf.setCharAt(max - 4, '.');
        return;
    }

    int first = (int) pos;
    int last = (int) max - 2;

    buf.setCharAt(first, buf.charAt(first));
    buf.setCharAt(last, buf.charAt(last));
    buf.setCharAt(last + 1, '.');

    if ((first + 2 < last) && (len >= 7)) {
        buf.setCharAt(first + 1, buf.charAt(first + 1));
        buf.setCharAt(last - 2, buf.charAt(last - 2));
        buf.setCharAt(last - 3, '.');
    }

    buf.setLength(last + 2);
}

