private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if (vertices.isEmpty()) {
        return true; // An empty graph or subgraph is trivially a clique
    }

    for (V vertex : vertices) {
        Set<V> neighbors = Graphs.successors(graph, vertex);
        for (V otherVertex : vertices) {
            if (vertex.equals(otherVertex)) {
                continue;
            }
            if (!neighbors.contains(otherVertex)) {
                return false; // If any vertex is not connected to another vertex, the subgraph is not a clique
            }
        }
    }

    return true; // All vertices are connected to each other, so the subgraph is a clique
}

