    if (firstByte == -1) {
        return 0;
    }
    int tag = (firstByte & 0x7f) << 3;
    int secondByte = in.read();
    if (secondByte == -1) {
        throw new IOException("Protocol message contained a tag with value zero.");
    }
    while ((secondByte & 0x80) != 0) {
        tag |= (secondByte & 0x7f) << shifts.pop();
        if (shifts.isEmpty()) {
            shifts.push(3);
        } else {
            shifts.pop();
            shifts.push(shifts.peek() + 7);
        }
        secondByte = in.read();
        if (secondByte == -1) {
            throw new IOException("Protocol message contained a tag with value zero.");
        }
    }
    tag |= secondByte;
    if (tag == 0) {
        throw new IOException("Protocol message contained a tag with value zero.");
    }
    return tag;
}

